def create_missing_profiles(apps, schema_editor):
    """
    Crea perfiles para usuarios existentes
    que todavía no tienen uno.
    """

    app_label, model_name = settings.AUTH_USER_MODEL.split(".")

    User = apps.get_model(app_label, model_name)
    UserProfile = apps.get_model(
        "accounts",
        "UserProfile",
    )

    db_alias = schema_editor.connection.alias

    users_without_profile = User.objects.using(db_alias).filter(profile__isnull=True)

    for user in users_without_profile.iterator():
        UserProfile.objects.using(db_alias).get_or_create(
            user_id=user.pk,
            defaults={
                "must_change_password": False,
            },
        )


